def nb(r,c,g,v=9):
    res=[]
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        rr,cc=r+dr,c+dc
        if 0<=rr<len(g) and 0<=cc<len(g[0]) and g[rr][cc]==v: res.append((rr,cc))
    return res
